"""Generate checked-in LVGL 8 assets; Pillow is needed only for regeneration."""

import argparse
from pathlib import Path

from PIL import Image


def generate():
    root = Path(__file__).resolve().parent.parent
    sources = sorted((root / "assets" / "dq72").glob("*.png"))
    if not sources:
        raise ValueError("No DQ72 PNG sources found")
    header = [
        "/* Generated by assets/generate.py from the original DQ72 PNGs. */",
        "#ifndef PRINTER_DEMO_SOUNDBOX_IMAGES_H",
        "#define PRINTER_DEMO_SOUNDBOX_IMAGES_H",
        "#include <lvgl/lvgl.h>",
    ]
    output = [
        header[0],
        '#include "soundbox_images.h"',
        "#if LV_COLOR_DEPTH != 16 && LV_COLOR_DEPTH != 32",
        '#error "DQ72 assets require RGB565 or BGRA32"',
        "#endif",
        "#if LV_COLOR_DEPTH == 16 && LV_COLOR_16_SWAP",
        '#error "DQ72 RGB565 assets require LV_COLOR_16_SWAP=0"',
        "#endif",
    ]
    for path in sources:
        with Image.open(path) as source:
            image = source.convert("RGBA")
            width, height = image.size
            if not (0 < width < 2048 and 0 < height < 2048):
                raise ValueError(f"Image exceeds LVGL descriptor limits: {path}")
            rgba = image.tobytes()
        name = f"soundbox_img_{path.stem}"
        header.append(f"extern const lv_img_dsc_t {name};")
        for depth in (16, 32):
            output.append(f"#if LV_COLOR_DEPTH == {depth}")
            pixels = bytearray()
            for offset in range(0, len(rgba), 4):
                red, green, blue, alpha = rgba[offset : offset + 4]
                if depth == 16:
                    rgb565 = ((red >> 3) << 11) | ((green >> 2) << 5) | (blue >> 3)
                    pixels.extend((rgb565 & 255, rgb565 >> 8, alpha))
                else:
                    pixels.extend((blue, green, red, alpha))
            output.append(f"static const uint8_t {name}_pixels[] = {{")
            for offset in range(0, len(pixels), 18):
                output.append("    " + ",".join(
                    f"0x{value:02x}" for value in pixels[offset : offset + 18]
                ) + ",")
            output.extend(("};", "#endif"))
        output.extend((
            f"const lv_img_dsc_t {name} = {{",
            f"    .header = {{.cf = LV_IMG_CF_TRUE_COLOR_ALPHA, .w = {width}, .h = {height}}},",
            f"    .data_size = sizeof({name}_pixels),",
            f"    .data = {name}_pixels",
            "};",
        ))
    header.append("#endif")
    return {
        root / "include" / "soundbox_images.h": "\n".join(header) + "\n",
        root / "src" / "soundbox_images.c": "\n".join(output) + "\n",
    }


if __name__ == "__main__":
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--check", action="store_true")
    args = parser.parse_args()
    for target, content in generate().items():
        if args.check:
            if not target.exists() or target.read_text(encoding="ascii") != content:
                parser.error(f"Stale generated asset: {target}; run assets/generate.py")
        else:
            target.write_text(content, encoding="ascii")
    print("DQ72 LVGL assets verified" if args.check else "DQ72 LVGL assets generated")
